const auth = $input.first().json.headers?.authorization || '';
if (!auth.startsWith('Bearer ')) return [{ json: { _error: 'AUTH_MISSING_TOKEN', _status: 401 } }];
const token = auth.slice(7);
try {
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
  if (!payload.sub) throw new Error('No sub');
  if (payload.exp && Date.now()/1000 > payload.exp) throw new Error('JWT expired');
  if (!payload.tenant_id) throw new Error('No tenant_id');
  const body = $input.first().json.body || {};
  const proposalId = (body.proposal_id || '').trim();
  if (!proposalId) return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'proposal_id requerido' } }];
  return [{ json: {
    user_id: payload.sub,
    tenant_id: payload.tenant_id,
    role: payload.role || 'architect',
    proposal_id: proposalId,
    force_regenerate: !!body.force_regenerate,
    request_id: 'req_' + Math.random().toString(36).slice(2, 10)
  }}];
} catch (e) {
  return [{ json: { _error: 'AUTH_INVALID_TOKEN', _status: 401, _details: e.message } }];
}

const sess = $('Decode JWT + Validate').first().json;
const proposalRows = $('Load Proposal + Project').all().map(i => i.json).filter(p => p && p.id);
if (proposalRows.length === 0) return [{ json: { _error: 'PROPOSAL_NOT_FOUND', _status: 404, _details: 'proposal_id no existe', request_id: sess.request_id }}];
const proposal = proposalRows[0];

if (proposal.moodboard_data && !sess.force_regenerate) {
  return [{ json: { _skip: true, _existing: proposal.moodboard_data, _public_token: proposal.public_token, _proposal_id: proposal.id, _project_id: proposal.project_id, request_id: sess.request_id }}];
}

const designRows = $('Load Design Option').all().map(i => i.json).filter(d => d && d.id);
const materialRows = $('Load Material Items').all().map(i => i.json).filter(m => m && m.id);
const briefingRows = $input.all().map(i => i.json).filter(b => b && b.summary);
const design = designRows[0] || null;
const briefing = briefingRows[0] || null;

const materialsByCategory = {};
materialRows.forEach(function(m) {
  const cat = m.category || 'otro';
  if (!materialsByCategory[cat]) materialsByCategory[cat] = [];
  materialsByCategory[cat].push((m.brand ? m.brand + ' ' : '') + (m.name || '') + (m.quality_tier ? ' (' + m.quality_tier + ')' : '') + (m.room_area ? ' [' + m.room_area + ']' : ''));
});
const materialsText = Object.keys(materialsByCategory).length
  ? Object.entries(materialsByCategory).map(function(e) { return '- ' + e[0] + ': ' + e[1].slice(0, 5).join('; '); }).join('\n')
  : '(sin materiales registrados)';

const systemPrompt = 'Eres agent_proposal_moodboard. Generas un MOODBOARD VISUAL para una propuesta de reforma. Output JSON estricto:\n\n{\n  "palette": [ { "name": "Greige calido", "hex": "#C9B89D", "role": "base/pared" }, ... 4-6 colores ],\n  "materials": [ { "name": "...", "category": "pavimento|revestimiento|...", "finish": "mate|brillo|texturizado", "role": "..." }, ... 6-12 items ],\n  "style_keywords": [ "mediterraneo contemporaneo", "calidez", "luz natural", ... 4-8 ],\n  "design_rationale": "3-5 frases para el cliente explicando por que estos materiales encajan con su brief y espacio. Lenguaje no tecnico.",\n  "render_prompt": "Texto en INGLES (max 200 chars) para alimentar mnml.ai Interior AI. Describe estilo, paleta principal, materiales clave, ambiente. Ej: photorealistic modern mediterranean kitchen, warm white walls, oak wood floor, brass fittings, soft natural light.",\n  "avoid": [ "...", "..." ]\n}\n\nREGLAS:\n- Los hex de paleta deben ser coherentes entre si (mismo undertone).\n- materials deben coincidir con los materiales reales listados, no inventes marcas.\n- design_rationale en espanol, render_prompt en ingles.\n- avoid: 2-3 cosas a evitar visualmente (ej: "colores saturados", "acabados industriales frios").';

const userPrompt = 'PROYECTO: ' + proposal.project_name + ' (' + (proposal.project_type || '?') + ', ' + (proposal.property_area_m2 || '?') + ' m2 en ' + (proposal.location_city || '?') + ')\n\n' +
  'PROPUESTA: ' + proposal.title + ' (total ' + proposal.total_price + ' EUR)\nALCANCE: ' + (proposal.scope_description || '').slice(0, 600) + '\n\n' +
  'BRIEFING:\n' + (briefing ? ('  summary: ' + (briefing.summary || '').slice(0, 300) + '\n  necesidades: ' + (typeof briefing.client_needs === 'object' ? JSON.stringify(briefing.client_needs).slice(0, 300) : (briefing.client_needs || '').slice(0, 300))) : '(sin briefing)') + '\n\n' +
  'OPCION DE DISENO SELECCIONADA:\n' + (design ? ('  ' + design.title + ' - ' + (design.description || '').slice(0, 400) + '\n  logica: ' + (design.intervention_logic || '').slice(0, 300)) : '(sin design_option seleccionada - usa briefing)') + '\n\n' +
  'MATERIALES REGISTRADOS POR CATEGORIA:\n' + materialsText + '\n\n' +
  'TAREA: construye el moodboard JSON. Si no hay materiales registrados, propon materiales tipicos para el estilo que infieras del briefing+design.';

return [{ json: {
  user_id: sess.user_id,
  tenant_id: sess.tenant_id,
  proposal_id: proposal.id,
  project_id: proposal.project_id,
  has_existing_token: !!proposal.public_token,
  existing_token: proposal.public_token,
  request_id: sess.request_id,
  llm_payload: {
    model: 'gpt-4o',
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userPrompt }
    ],
    temperature: 0.4,
    max_tokens: 1200,
    response_format: { type: 'json_object' }
  }
}}];

const llm = $input.first()?.json;
const built = $('Build Prompt').first().json;
const raw = llm?.choices?.[0]?.message?.content || '{}';
let parsed;
try { parsed = JSON.parse(raw); } catch (e) {
  return [{ json: { _error: 'LLM_INVALID_JSON', _status: 502, _details: e.message, _raw: raw.slice(0, 500), request_id: built.request_id }}];
}
const usage = llm?.usage || {};

const publicToken = built.has_existing_token
  ? built.existing_token
  : (Math.random().toString(36).slice(2) + Date.now().toString(36) + Math.random().toString(36).slice(2)).slice(0, 24);

const expiresAt = new Date(Date.now() + 60 * 24 * 60 * 60 * 1000).toISOString();

return [{ json: {
  proposal_id: built.proposal_id,
  project_id: built.project_id,
  request_id: built.request_id,
  moodboard: {
    palette: Array.isArray(parsed.palette) ? parsed.palette.slice(0, 8) : [],
    materials: Array.isArray(parsed.materials) ? parsed.materials.slice(0, 16) : [],
    style_keywords: Array.isArray(parsed.style_keywords) ? parsed.style_keywords.slice(0, 10) : [],
    design_rationale: parsed.design_rationale || null,
    render_prompt: parsed.render_prompt || null,
    avoid: Array.isArray(parsed.avoid) ? parsed.avoid.slice(0, 5) : [],
    generated_at: new Date(Date.now()).toISOString(),
    model: llm?.model || 'gpt-4o'
  },
  public_token: publicToken,
  public_token_was_generated: !built.has_existing_token,
  public_token_expires_at: expiresAt,
  tokens_in: usage.prompt_tokens || 0,
  tokens_out: usage.completion_tokens || 0,
  model: llm?.model || 'gpt-4o'
}}];

const skipPath = $('Skip (already exists)?').isExecuted && $('Build Prompt').first().json._skip;
if (skipPath) {
  const sk = $('Build Prompt').first().json;
  return [{ json: { data: { proposal_id: sk._proposal_id, project_id: sk._project_id, moodboard: sk._existing, public_token: sk._public_token, already_existed: true }, meta: { request_id: sk.request_id, source: 'cached' } } }];
}
const f = $('Format Moodboard').first().json;
const upd = $('Update Proposal').isExecuted ? ($('Update Proposal').first()?.json || {}) : {};
return [{ json: {
  data: {
    proposal_id: f.proposal_id,
    project_id: f.project_id,
    moodboard: f.moodboard,
    public_token: upd.public_token || f.public_token,
    public_token_expires_at: upd.public_token_expires_at || f.public_token_expires_at,
    public_token_was_generated: f.public_token_was_generated,
    already_existed: false
  },
  meta: {
    request_id: f.request_id,
    model: f.model,
    tokens_in: f.tokens_in,
    tokens_out: f.tokens_out
  }
}}];
